        private void CheckConfig(string Path, string ConfigData, Boolean UpData)
        {
            var sss = Path.Split('/');
            MyCommond.WriteLog(ThisReceive, $"檢查檔案 {sss[sss.Length - 1]}");
            Boolean FirstCheck = MyCommond.CheckFile(Path);
            if (Status_Config_Updata_mContorl && UpData)
            {
                DateTime TmPg = Convert.ToDateTime(File.GetLastWriteTime(System.Diagnostics.Process.GetCurrentProcess().MainModule.FileName));
                //DateTime TmPg = Convert.ToDateTime(Directory.GetCreationTime(this.GetType().Assembly.Location));
                DateTime TmCf = Convert.ToDateTime(Directory.GetCreationTime(Path));
                if (TmPg > TmCf) { File.Delete(Path); }
            }

            if (!MyCommond.CheckFile(Path))
            {
                //this.WriteLog(ExecutionMode.Simple, $"{Path}," + ((FirstCheck) ? "有發現此檔案，開始更新資料" : "未發現此檔案，開始建立資料"));
                File.WriteAllText(Path, ConfigData, Encoding.UTF8);
            }
        }

        private List<TResult> Load2Model<TResult>(string path, string mTitle, Boolean UpData, string Data, int JumpLine = 0) where TResult : class, new()
        {
            var sss = path.Split('/');
            CheckConfig(path, Data, UpData);
            MyCommond.WriteLog(ThisReceive, $"載入檔案{sss[sss.Length - 1]}");
            return MyCommond.ToViewModel<TResult>(ThisReceive, path, mTitle, JumpLine);
        }

